* { margin: 0; padding: 0; box-sizing: border-box; }
html { overflow-x: hidden; }
body { font-family: 'Source Sans 3', sans-serif; background: var(--cream); color: var(--dark); overflow-x: hidden; }

/* CARD BACKGROUND COLORS c1-c9 */
.card-img.c1 { background: linear-gradient(135deg,#1a2a3a,#2c4a6e); }
.card-img.c2 { background: linear-gradient(135deg,#1a3020,#2e6040); }
.card-img.c3 { background: linear-gradient(135deg,#3a1a1a,#7a2020); }
.card-img.c4 { background: linear-gradient(135deg,#1a2a3a,#304060); }
.card-img.c5 { background: linear-gradient(135deg,#2a1a3a,#5a3070); }
.card-img.c6 { background: linear-gradient(135deg,#1a2a1a,#2a5030); }
.card-img.c7 { background: linear-gradient(135deg,#2a2a1a,#605020); }
.card-img.c8 { background: linear-gradient(135deg,#1a3028,#1e6048); }
.card-img.c9 { background: linear-gradient(135deg,#2a1a10,#704020); }
.card-img { position: relative; }
.card-img > .cat-tag { position: absolute; bottom: 0; left: 0; z-index: 2; }
/* emoji centering in c-class cards */
.card-img.c1::before,.card-img.c2::before,.card-img.c3::before,.card-img.c4::before,
.card-img.c5::before,.card-img.c6::before,.card-img.c7::before,.card-img.c8::before,
.card-img.c9::before { content:''; position:absolute;inset:0; background:rgba(0,0,0,.15); }
.card-img > span { position: relative; z-index: 1; font-size: 44px; }

/* HERO IMAGE background for sections */
.hero-img.c1 { background: linear-gradient(135deg,#0a1a2e,#1a3a5a); }
.hero-img.c2 { background: linear-gradient(135deg,#0a2010,#1a5030); }
.hero-img.c3 { background: linear-gradient(135deg,#2a0a0a,#5a1a1a); }
.hero-img.c4 { background: linear-gradient(135deg,#0a1828,#1a3050); }
.hero-img.c5 { background: linear-gradient(135deg,#1a0a2a,#3a1a60); }
.hero-img.c6 { background: linear-gradient(135deg,#0a1808,#1a4020); }
.hero-img.c7 { background: linear-gradient(135deg,#1a1804,#504010); }
.hero-img.c8 { background: linear-gradient(135deg,#0a2018,#104028); }
.hero-img.c9 { background: linear-gradient(135deg,#201408,#502a10); }

