/* MODAL */
.modal-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.65); z-index: 999; align-items: flex-start; justify-content: center; padding: 40px 20px; overflow-y: auto; }
.modal-overlay.open { display: flex; }
.modal { background: var(--white); max-width: 740px; width: 100%; position: relative; overflow: hidden; }
.modal-header-img { width: 100%; height: 240px; object-fit: cover; display: block; }
.modal-inner { padding: 32px 36px; }
.modal-close { position: absolute; top: 12px; right: 12px; background: rgba(0,0,0,.55); border: none; font-size: 18px; cursor: pointer; color: var(--white); width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; z-index: 10; }
.modal-tag { display: inline-block; background: var(--red); color: var(--white); font-family: 'Source Sans 3', sans-serif; font-size: 9px; font-weight: 700; padding: 4px 10px; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 14px; }
.modal h2 { font-family: 'Playfair Display', serif; font-size: 26px; line-height: 1.4; margin-bottom: 10px; font-weight: 700; color: var(--dark); }
.modal .meta { font-family: 'Source Sans 3', sans-serif; font-size: 12px; color: var(--gray); margin-bottom: 22px; padding-bottom: 18px; border-bottom: 1px solid var(--border); }
.modal-body p { font-size: 16px; line-height: 1.85; color: #333; margin-bottom: 16px; }
.modal-body h3 { font-family: 'Playfair Display', serif; font-size: 19px; margin: 24px 0 10px; color: var(--green); font-weight: 700; }

