function closeModalOutside(e) {
  if (e.target === document.getElementById('articleModal')) closeModal();
}

document.addEventListener('keydown', e => { if(e.key === 'Escape') closeModal(); });

// ===== AUTO-OPEN ARTICLE FROM URL PARAMS =====
(function() {
  const params = new URLSearchParams(window.location.search);
  const id = params.get('id');
  if (id) {
    if (document.readyState === 'complete') {
      setTimeout(function() { openArticle(id); }, 100);
    } else {
      window.addEventListener('load', function() {
        setTimeout(function() { openArticle(id); }, 100);
      });
    }
  }
})();

// ===== NEWSLETTER =====
function subscribeNL() {
  const email = document.getElementById('nlEmail').value;
  if (!email || !email.includes('@')) { alert('Veuillez entrer une adresse email valide.'); return; }
  document.getElementById('nlForm').style.display = 'none';

