document.addEventListener('keydown', e => { if(e.key === 'Escape') closeModal(); });

// ===== SHARE =====
let _currentArticleTitle = '';
function shareArticle(platform) {
  const url = encodeURIComponent(window.location.href);
  const text = encodeURIComponent(_currentArticleTitle + ' — AfriPolitique');
  if (platform === 'twitter') window.open('https://twitter.com/intent/tweet?text=' + text + '&url=' + url, '_blank');
  else if (platform === 'facebook') window.open('https://www.facebook.com/sharer/sharer.php?u=' + url, '_blank');
  else if (platform === 'whatsapp') window.open('https://wa.me/?text=' + text + '%20' + url, '_blank');
}

// ===== BACK TO TOP =====
window.addEventListener('scroll', function() {
  const btn = document.getElementById('backTop');
  if (btn) btn.style.display = window.scrollY > 400 ? 'flex' : 'none';
  if (btn) btn.style.alignItems = 'center';
  if (btn) btn.style.justifyContent = 'center';
});

